import { createRequire } from 'node:module';
const req = createRequire('C:/Users/user/AppData/Local/Temp/skill-eval-lD7vPI/package.json');
const mapValues = req('lodash/mapValues.js'), keyBy = req('lodash/keyBy.js'), fromPairs = req('lodash/fromPairs.js');
const mig = await import('./mig.mjs');
const assert = (c, m) => { if (!c) throw new Error(m); };
const same = (a, b) => JSON.stringify(a) === JSON.stringify(b) && Object.keys(a).join() === Object.keys(b).join();
const NAMES = ['kim','lee','park','jung','choi'];
const rnd = (a, b) => a + Math.floor(Math.random() * (b - a + 1));
const pick = a => a[rnd(0, a.length - 1)];
let n = 0;
const origDoubled = s => mapValues(s, v => v * 2);
const origBy = r => keyBy(r, 'name');
const origLookup = p => fromPairs(p);
const cases = [];
// examples
cases.push(['doubled', [{jung:43,park:16}], origDoubled, mig.doubled]);
cases.push(['doubled', [{}], origDoubled, mig.doubled]);
cases.push(['byNameKey', [[]], origBy, mig.byNameKey]);
const rows = [{id:9,name:'kim',age:34},{id:3,name:'park',age:57},{id:2,name:'jung',age:58},{id:1,name:'lee',age:47},{id:5,name:'park',age:30},{id:3,name:'lee',age:40},{id:0,name:'park',age:19},{id:0,name:'lee',age:24},{id:0,name:'kim',age:51},{id:4,name:'park',age:45},{id:7,name:'kim',age:37},{id:9,name:'lee',age:51}];
cases.push(['byNameKey', [rows], origBy, mig.byNameKey]);
cases.push(['toLookup', [[['kim',57],['jung',57],['kim',72],['choi',59],['jung',53],['lee',28]]], origLookup, mig.toLookup]);
cases.push(['toLookup', [[['kim',35],['lee',1],['jung',41],['park',11],['jung',39],['jung',92]]], origLookup, mig.toLookup]);
// random
for (let i = 0; i < 20000; i++) {
  const o = {}; const k = rnd(0,5); for (let j=0;j<k;j++) o[pick(NAMES)] = rnd(-5,99);
  cases.push(['doubled', [o], origDoubled, mig.doubled]);
  const r = Array.from({length: rnd(0,12)}, () => ({id: rnd(0,9), name: pick(NAMES), age: rnd(18,60)}));
  cases.push(['byNameKey', [r], origBy, mig.byNameKey]);
  const p = Array.from({length: rnd(0,8)}, () => [pick(NAMES), rnd(-5,99)]);
  cases.push(['toLookup', [p], origLookup, mig.toLookup]);
}
for (const [name, args, orig, mine] of cases) {
  const a = orig(...args), b = mine(...args);
  assert(same(a, b), `${name} mismatch: ${JSON.stringify(args)} => ${JSON.stringify(a)} vs ${JSON.stringify(b)}`);
  n++;
}
console.log('all equal:', n, 'cases');
EOF
